/// `unicodedata.east_asian_width(chr(code_point))`。
pub fn east_asian_width(code_point: u32) -> Option<&'static str> {
    lookup(EAST_ASIAN_WIDTH_RANGES, code_point)
}

/// 稀疏表共用的按码点二分查找（表按码点升序、无重复）。
fn lookup_sparse<T: Copy>(entries: &[(u32, T)], code_point: u32) -> Option<T> {
    let mut low = 0usize;
    let mut high = entries.len();
    while low < high {
        let middle = (low + high) / 2;
        let (key, value) = entries[middle];
        if code_point < key {
            high = middle;
        } else if code_point > key {
            low = middle + 1;
        } else {
            return Some(value);
        }
    }
    None
}

