/// `unicodedata.digit(chr(code_point))`。
pub fn digit(code_point: u32) -> Option<u32> {
    lookup_sparse(DIGIT_VALUES, code_point)
}

/// 数值（`unicodedata.numeric`）：**约分对** `(分子, 分母)`——`numeric` 的内部表示
/// 就是分数（`float.as_integer_ratio()` 取到的就是它）；整数写作 `(值, 1)`。
/// 分子是**有符号**的：参照实现里确有负值（如 `U+0F33` ⇒ `-1/2`）。
/// 分母用 `u64`：浮点的**精确**比值可以很大（如 `2^59`），而它是 2 的幂 ⇒
/// 转 `f64` 仍然精确，除法与参照实现逐位相同。
