/// `unicodedata.numeric(chr(code_point))`（按约分对算回浮点）。
pub fn numeric(code_point: u32) -> Option<f64> {
    let mut low = 0usize;
    let mut high = NUMERIC_VALUES.len();
    while low < high {
        let middle = (low + high) / 2;
        let (key, numerator, denominator) = NUMERIC_VALUES[middle];
        if code_point < key {
            high = middle;
        } else if code_point > key {
            low = middle + 1;
        } else {
            return Some(numerator as f64 / denominator as f64);
        }
    }
    None
}

